class Solution {
    public String convert(String s, int numRows) {
        if (numRows == 1) {
            return s;
        }

        int rowCount = Math.min(numRows, s.length());
        char[][] grid = new char[rowCount][s.length()];
        int row = 0;
        int column = 0;
        boolean movingDown = true;

        for (int index = 0; index < s.length(); index++) {
            grid[row][column] = s.charAt(index);
            if (row == rowCount - 1) {
                movingDown = false;
            } else if (row == 0) {
                movingDown = true;
            }

            if (movingDown) {
                row++;
            } else {
                row--;
                column++;
            }
        }

        StringBuilder result = new StringBuilder(s.length());
        for (int currentRow = 0; currentRow < rowCount; currentRow++) {
            for (int currentColumn = 0; currentColumn < s.length(); currentColumn++) {
                if (grid[currentRow][currentColumn] != '\0') {
                    result.append(grid[currentRow][currentColumn]);
                }
            }
        }
        return result.toString();
    }
}

